import{_ as t,o as s,c as a,a2 as r,j as o}from"./chunks/framework.D66Xq0Kv.js";const n="/assets/drawer-add-results.DyYBFb23.png",i="/assets/drawer-view.CWCrUyHN.png",d="/assets/drawer-permissions.F9KQdNo4.png",h="/assets/drawer-create-group.U3VoWSlF.png",D=JSON.parse('{"title":"Working with Drawers","description":"","frontmatter":{},"headers":[],"relativePath":"using-drawers.md","filePath":"using-drawers.md"}'),c={name:"using-drawers.md"};function g(l,e,p,w,u,m){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="working-with-drawers" tabindex="-1">Working with Drawers <a class="header-anchor" href="#working-with-drawers" aria-label="Permalink to &quot;Working with Drawers&quot;">​</a></h1><p>Drawers are user-defined groups of assets. Given appropriate permissions, users of your instance can create drawers, add assets to those drawers, and share them with other users. Drawers can also store video excerpts - clips of longer videos which can be linked to directly.</p><h2 id="creating-drawers" tabindex="-1">Creating Drawers <a class="header-anchor" href="#creating-drawers" aria-label="Permalink to &quot;Creating Drawers&quot;">​</a></h2><p>To see your drawers, open the main menu and choose <strong>Drawers</strong>. To create an empty drawer there, click <strong>Create Drawer</strong>, enter a <strong>Drawer Title</strong>, and click <strong>Create</strong>.</p><p>You can also create a drawer at the moment you add assets to it. See <a href="#adding-assets-to-a-drawer">Adding Assets to a Drawer</a>.</p><h2 id="adding-assets-to-a-drawer" tabindex="-1">Adding Assets to a Drawer <a class="header-anchor" href="#adding-assets-to-a-drawer" aria-label="Permalink to &quot;Adding Assets to a Drawer&quot;">​</a></h2><p>You can add assets to a drawer from either an individual asset or the search results page.</p><ul><li><strong>From an asset:</strong> click the drawer icon (<strong>Add to Drawer</strong>) in the toolbar below the file viewer. Choose an <strong>Existing Drawer</strong>, or type a name in <strong>New Drawer</strong> to create one, and click <strong>Add to Drawer</strong>.</li><li><strong>From search results:</strong> click the drawer icon (<strong>Add Search Results to Drawer</strong>) at the right end of the results bar. This adds only the results loaded so far, the first number in a count such as &quot;30 of 120 results&quot;. To add them all, click <strong>Load All</strong> (or <strong>Load More</strong>) next to the count first. Choose a drawer and click <strong>Add to Drawer</strong>, or type a new drawer title and click <strong>Create Drawer</strong> to create a drawer and add the results to it.</li></ul><p><img src="'+n+'" alt="The Add Search Results to Drawer dialog, with a drawer menu and a New Drawer Title field"></p><h2 id="viewing-a-drawer" tabindex="-1">Viewing a Drawer <a class="header-anchor" href="#viewing-a-drawer" aria-label="Permalink to &quot;Viewing a Drawer&quot;">​</a></h2><p>Open a drawer from the <strong>Drawers</strong> page to see its assets. The drawer has the same <strong>Grid</strong>, <strong>List</strong>, <strong>Timeline</strong>, <strong>Map</strong>, and <strong>Gallery</strong> views as search results. To remove an asset from the drawer, switch to <strong>Grid</strong> view, click the × on its card, and then click <strong>Remove</strong>.</p><p><img src="'+i+'" alt="A drawer named Field Trip Readings, with two assets and the permissions and download icons at the upper right"></p><p>The icons at the upper right open the drawer&#39;s permissions (<strong>Edit Permissions</strong>) and download the drawer (<strong>Download Drawer</strong>).</p><h2 id="drawer-permissions" tabindex="-1">Drawer Permissions <a class="header-anchor" href="#drawer-permissions" aria-label="Permalink to &quot;Drawer Permissions&quot;">​</a></h2><p>Drawer permissions can be kind of complicated. Feel free to reach out to us directly for help.</p><p>Drawers follow the same permissions setup as the rest of Elevator, with the exception that Drawers don’t have a concept of “administration”.</p><p>Begin by opening your drawer from the <strong>Drawers</strong> page. Then click the people icon (<strong>Edit Permissions</strong>) at the upper right. The <strong>Drawer Permissions</strong> page lists the groups that can use the drawer and the permission each one has, along with any other groups you own. A new drawer starts with one group: you, with <strong>Create/Edit Drawers</strong>. To give one of your existing groups access, choose <strong>Edit Group</strong> from its <strong>⋮</strong> menu and pick a permission.</p><p><img src="'+d+'" alt="The Drawer Permissions page for Field Trip Readings, listing one group"></p><p>To share the drawer with more people, click <strong>Create Group</strong>. Choose a <strong>Group Type</strong>, enter a <strong>Group Name</strong>, choose a <strong>Permission</strong>, and click <strong>Create</strong>. The new group&#39;s row then opens with a form to add people (<strong>Add Member</strong>) or values such as a course (<strong>Add Entry</strong>). Types marked &quot;(admin only)&quot; can only be chosen by instance administrators. The types available depend on how your institution connects to Elevator. At the University of Minnesota, choose <strong>Class Number</strong> or <strong>Dept/Course Number</strong> to share a drawer with a course. <strong>Dept/Course Number</strong> accepts <code>%</code> as a wildcard, such as <code>DEPT.NUMBER%</code> to include every section. See <a href="/permissions.html#groups">Groups</a> for what each type means.</p><p><img src="'+h+'" alt="The Create Group dialog, with Group Type, Group Name, and Permission fields"></p><p>See the screencast below for a walkthrough.</p>',21),o("iframe",{width:"100%",height:"480",src:"https://www.youtube.com/embed/sJqRTntThMY",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1),r('<h2 id="video-excerpts" tabindex="-1">Video Excerpts <a class="header-anchor" href="#video-excerpts" aria-label="Permalink to &quot;Video Excerpts&quot;">​</a></h2><p>Elevator has the ability to save snippets of video (called excerpts) within drawers.</p><p>When viewing a video or audio file, click the drawer icon (<strong>Add to Drawer</strong>) in the toolbar below the player, and choose a drawer as above. Select <strong>Add as Excerpt</strong>, and give the excerpt an <strong>Excerpt Name</strong>. A player appears in the dialog. Play the file there, and when it reaches the start of your clip, click <strong>Set</strong> next to <strong>Start Time</strong>. When it reaches the end, click <strong>Set</strong> next to <strong>End Time</strong>. You can also type the times, as minutes and seconds (MM:SS) or hours, minutes, and seconds (HH:MM:SS). Finally, click <strong>Add to Drawer</strong>.</p>',3)])])}const y=t(c,[["render",g]]);export{D as __pageData,y as default};
